create table api_keys (active bit, created_at datetime(6) not null, id bigint not null auto_increment, user_id bigint not null, api_key varchar(255), provider varchar(255), primary key (id)) engine=InnoDB;
create table learning_sessions (accumulated_overlap_seconds integer not null, overlapping_duration_seconds integer, user1_uid integer, user2_uid integer, created_at datetime(6) not null, ended_at datetime(6), id bigint not null auto_increment, matched_at datetime(6) not null, reconnect_deadline datetime(6), started_at datetime(6), updated_at datetime(6) not null, user1_id bigint not null, user1_joined_agora_at datetime(6), user1_left_agora_at datetime(6), user2_id bigint not null, user2_joined_agora_at datetime(6), user2_left_agora_at datetime(6), channel_name varchar(100) not null, tag_snapshot varchar(100) not null, completion_reason enum ('BOTH_LEFT','CANCELLED_BY_SYSTEM','CANCELLED_BY_USER','INSUFFICIENT_DURATION','MATCH_TIMEOUT','MAX_DURATION_REACHED','ONE_LEFT_TIMEOUT','TECHNICAL_FAILURE'), level_snapshot enum ('N1','N2','N3','N4','N5') not null, status enum ('CANCELLED','COMPLETED','INCOMPLETE','IN_PROGRESS','MATCHED') not null, primary key (id)) engine=InnoDB;
create table peer_ratings (total_score integer not null, created_at datetime(6) not null, id bigint not null auto_increment, ratee_id bigint not null, rater_id bigint not null, session_id bigint, comment varchar(500), detail_scores TEXT, primary key (id)) engine=InnoDB;
create table practice_histories (duration_in_seconds integer, is_passed bit, phase integer not null, end_time datetime(6), id bigint not null auto_increment, script_id bigint not null, start_time datetime(6) not null, user_id bigint not null, ai_feedback TEXT, primary key (id)) engine=InnoDB;
create table rubrics (is_active bit not null, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, display_name varchar(100) not null, description TEXT, criteria enum ('ACCURACY','BODY_LANGUAGE','CONTENT_INTERESTINGNESS','ENTHUSIASM_CONFIDENCE','FLUENCY','PRONUNCIATION_INTONATION','STRUCTURE_LOGIC') not null, primary key (id)) engine=InnoDB;
create table script_read_status (id bigint not null auto_increment, read_at datetime(6) not null, script_id bigint not null, user_id bigint not null, primary key (id)) engine=InnoDB;
create table scripts (target_duration integer, id bigint not null auto_increment, tag_id bigint not null, content TEXT not null, language varchar(255) not null, meaning_content TEXT, phonetic varchar(255), title varchar(255) not null, primary key (id)) engine=InnoDB;
create table session_presence (is_open tinyint, created_at datetime(6) not null, id bigint not null auto_increment, joined_at datetime(6) not null, left_at datetime(6), session_id bigint not null, user_id bigint not null, primary key (id)) engine=InnoDB;
create table social_accounts (id bigint not null auto_increment, user_id bigint not null, provider varchar(255) not null, provider_id varchar(255) not null, primary key (id)) engine=InnoDB;
create table tag_categories (active bit not null, display_order integer not null, id bigint not null auto_increment, name varchar(255) not null, type enum ('ACTIVITY','LEVEL','TOPIC') not null, primary key (id)) engine=InnoDB;
create table tags (category_id bigint not null, id bigint not null auto_increment, name varchar(255) not null, primary key (id)) engine=InnoDB;
create table user_ai_settings (id bigint not null auto_increment, user_id bigint not null, ai_api_key TEXT not null, ai_provider enum ('GEMINI','GROK') not null, primary key (id)) engine=InnoDB;
create table users (trust_score float(23) not null, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, avatar_public_id varchar(255), avatar_url varchar(255), email varchar(255) not null, username varchar(255) not null, active_ai_provider enum ('GEMINI','GROK'), current_level enum ('N1','N2','N3','N4','N5') not null, role enum ('ADMIN','USER') not null, status enum ('ACTIVE','DISABLED') not null, primary key (id)) engine=InnoDB;
